create or replace function private.is_linked_employee_of_business(p_business_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.employees e where e.business_id=p_business_id and e.user_id=(select auth.uid()) and e.is_active) $$;
create or replace function private.appointment_party_can_read_profile(p_profile_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.appointments a where a.customer_id=p_profile_id and (exists(select 1 from public.employees e where e.id=a.employee_id and e.user_id=(select auth.uid()) and e.is_active) or exists(select 1 from public.businesses b where b.id=a.business_id and b.owner_id=(select auth.uid())))) $$;
drop policy if exists "appointment parties read" on public.appointments;
create policy "appointment parties read" on public.appointments for select to authenticated using(customer_id=(select auth.uid()) or exists(select 1 from public.employees e where e.id=appointments.employee_id and e.user_id=(select auth.uid()) and e.is_active) or exists(select 1 from public.businesses b where b.id=appointments.business_id and b.owner_id=(select auth.uid())));
drop policy if exists "employees read their services" on public.services;
create policy "employees read their services" on public.services for select to authenticated using(exists(select 1 from public.employees e where e.business_id=services.business_id and e.user_id=(select auth.uid()) and e.is_active));
drop policy if exists "employee hours manage" on public.employee_hours;
create policy "employee hours manage" on public.employee_hours for all to authenticated using(exists(select 1 from public.employees e where e.id=employee_hours.employee_id and e.user_id=(select auth.uid()) and e.is_active) or exists(select 1 from public.employees e join public.businesses b on b.id=e.business_id where e.id=employee_hours.employee_id and b.owner_id=(select auth.uid()))) with check(exists(select 1 from public.employees e where e.id=employee_hours.employee_id and e.user_id=(select auth.uid()) and e.is_active) or exists(select 1 from public.employees e join public.businesses b on b.id=e.business_id where e.id=employee_hours.employee_id and b.owner_id=(select auth.uid())));
drop policy if exists "employee breaks manage" on public.employee_breaks;
create policy "employee breaks manage" on public.employee_breaks for all to authenticated using(exists(select 1 from public.employees e where e.id=employee_breaks.employee_id and e.user_id=(select auth.uid()) and e.is_active) or exists(select 1 from public.employees e join public.businesses b on b.id=e.business_id where e.id=employee_breaks.employee_id and b.owner_id=(select auth.uid()))) with check(exists(select 1 from public.employees e where e.id=employee_breaks.employee_id and e.user_id=(select auth.uid()) and e.is_active) or exists(select 1 from public.employees e join public.businesses b on b.id=e.business_id where e.id=employee_breaks.employee_id and b.owner_id=(select auth.uid())));
drop policy if exists "employee time off manage" on public.employee_time_off;
create policy "employee time off manage" on public.employee_time_off for all to authenticated using(exists(select 1 from public.employees e where e.id=employee_time_off.employee_id and e.user_id=(select auth.uid()) and e.is_active) or exists(select 1 from public.employees e join public.businesses b on b.id=e.business_id where e.id=employee_time_off.employee_id and b.owner_id=(select auth.uid()))) with check(exists(select 1 from public.employees e where e.id=employee_time_off.employee_id and e.user_id=(select auth.uid()) and e.is_active) or exists(select 1 from public.employees e join public.businesses b on b.id=e.business_id where e.id=employee_time_off.employee_id and b.owner_id=(select auth.uid())));
create or replace function public.update_appointment_status(p_appointment_id uuid,p_status text) returns void language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null then raise exception 'Giriş yapmalısınız'; end if; if p_status not in ('confirmed','cancelled','completed','no_show') then raise exception 'Geçersiz durum'; end if; update public.appointments a set status=p_status where a.id=p_appointment_id and (exists(select 1 from public.businesses b where b.id=a.business_id and b.owner_id=auth.uid()) or exists(select 1 from public.employees e where e.id=a.employee_id and e.user_id=auth.uid() and e.is_active)); if not found then raise exception 'Randevu bulunamadı veya işlem yetkiniz yok'; end if; end $$;